// Public install assets and a strictly bounded device-local thumbnail cache.
export const galleryManifest = "{\"id\":\"/\",\"name\":\"我的相册\",\"short_name\":\"相册\",\"description\":\"私人照片、视频与网盘回忆\",\"lang\":\"zh-CN\",\"start_url\":\"/\",\"scope\":\"/\",\"display\":\"standalone\",\"background_color\":\"#101114\",\"theme_color\":\"#101114\",\"icons\":[{\"src\":\"/@gallery-icon-192.png\",\"sizes\":\"192x192\",\"type\":\"image/png\",\"purpose\":\"any maskable\"},{\"src\":\"/@gallery-icon-512.png\",\"sizes\":\"512x512\",\"type\":\"image/png\",\"purpose\":\"any maskable\"}]}"
export const galleryServiceWorker = "// Private, bounded, device-local thumbnail cache. Never cache HTML, APIs,\n// original media, credentials or navigation. The browser, not the Worker,\n// fetches upstream previews. A route is usable only by a gallery client that\n// registered it via the in-memory message channel.\nconst READABLE=\"gallery-thumb-readable-v1\",OPAQUE=\"gallery-thumb-opaque-v1\";\nconst MAX_READABLE=256,MAX_OPAQUE=48,MAX_BYTES=192*1024,TTL_DAYS=7;\nconst routes=new Map(),corsModes=new Map(),keyRevisions=new Map(),deletions=new Map();\nlet generation=0,writes=Promise.resolve(),clearing=null,quotaCheck=0,opaqueAllowed=true;\nconst keyOK=k=>typeof k===\"string\"&&/^[a-f0-9]{64}$/.test(k);\nconst routePath=k=>\"/@gallery-thumb/\"+k;\nconst cacheKey=k=>new URL(routePath(k),self.location.origin).href;\nconst day=()=>Math.floor(Date.now()/86400000);\nfunction galleryClient(client){try{const u=new URL(client.url);return u.origin===self.location.origin&&(u.pathname===\"/\"||u.pathname===\"/@gallery\")}catch{return false}}\nfunction thumbnailURL(value){\n if(!value)return \"\";\n try{const u=new URL(value);return u.protocol===\"https:\"&&u.origin!==self.location.origin&&!u.username&&!u.password&&u.href.length<=4096?u.href:\"\"}catch{return \"\"}\n}\nfunction serial(fn){const next=writes.catch(()=>{}).then(fn);writes=next.catch(()=>{});return next}\nasync function removeCached(key){\n for(const name of [READABLE,OPAQUE]){\n  const cache=await caches.open(name);await cache.delete(cacheKey(key),{ignoreSearch:true})\n }\n}\nasync function clearThumbnails(){\n generation++;routes.clear();keyRevisions.clear();deletions.clear();\n const job=serial(async()=>{await Promise.all([caches.delete(READABLE),caches.delete(OPAQUE)])});\n clearing=job;try{await job}finally{if(clearing===job)clearing=null}\n}\nself.addEventListener(\"install\",()=>self.skipWaiting());\nself.addEventListener(\"activate\",e=>e.waitUntil(self.clients.claim()));\nself.addEventListener(\"message\",e=>{\n const m=e.data||{},client=e.source;\n if(!galleryClient(client))return;\n if(m.type===\"gallery-thumb-clear\"){e.waitUntil(clearThumbnails().catch(()=>{}));return}\n if(m.type===\"gallery-thumb-drop\"&&keyOK(m.key)){\n  const key=m.key;\n  keyRevisions.delete(key);keyRevisions.set(key,Symbol());\n  while(keyRevisions.size>1024)keyRevisions.delete(keyRevisions.keys().next().value);\n  const job=serial(()=>removeCached(key)).catch(()=>{});deletions.set(key,job);\n  e.waitUntil(job.finally(()=>{if(deletions.get(key)===job)deletions.delete(key)}));return\n }\n if(m.type!==\"gallery-thumb-map\"||!keyOK(m.key))return;\n const url=thumbnailURL(m.url);\n if(m.url&&!url){e.ports[0]?.postMessage(false);return}\n // Maps are ephemeral and scoped to the requesting browser tab.\n const key=client.id+\":\"+m.key;routes.delete(key);routes.set(key,{url,priority:m.priority===true,until:Date.now()+5*60000});\n while(routes.size>1024)routes.delete(routes.keys().next().value);\n e.ports[0]?.postMessage(true)\n});\nasync function cachedThumbnail(key){\n if(clearing)await clearing.catch(()=>{});\n if(deletions.has(key))await deletions.get(key);\n for(const name of [READABLE,OPAQUE]){\n  const cache=await caches.open(name),req=(await cache.keys(cacheKey(key),{ignoreSearch:true}))[0];\n  if(!req)continue;\n  const stamp=Number(new URL(req.url).searchParams.get(\"d\"));\n  if(!Number.isFinite(stamp)||stamp<day()-TTL_DAYS+1||stamp>day()){await cache.delete(req);continue}\n  const value=await cache.match(req);\n  if(value)return value\n }\n return null\n}\nasync function canStoreOpaque(){\n if(Date.now()-quotaCheck<30000)return opaqueAllowed;\n quotaCheck=Date.now();\n try{const q=await self.navigator.storage?.estimate();opaqueAllowed=!q?.quota||Number(q.usage||0)<q.quota*.7}catch{opaqueAllowed=true}\n return opaqueAllowed\n}\nasync function readSmallImage(res){\n const type=String(res.headers.get(\"content-type\")||\"\").split(\";\")[0].trim().toLowerCase();\n if(!/^image\\/(jpeg|png|webp|avif|gif|bmp|x-icon)$/.test(type)||Number(res.headers.get(\"content-length\")||0)>MAX_BYTES||!res.body)return null;\n const reader=res.body.getReader(),chunks=[];let total=0,finished=false;\n try{\n  while(true){const {done,value}=await reader.read();if(done){finished=true;break}total+=value.byteLength;if(total>MAX_BYTES)return null;chunks.push(value)}\n  return total?new Blob(chunks,{type}):null\n }finally{if(!finished)reader.cancel().catch(()=>{})}\n}\nasync function persistThumbnail(key,res,gen,revision,priority){\n const current=()=>gen===generation&&revision===keyRevisions.get(key);\n if(!current())return;\n const opaque=res.type===\"opaque\";\n let payload=res;\n if(opaque){if(!await canStoreOpaque())return}\n else{\n  if(!res.ok)return;\n  const blob=await readSmallImage(res);if(!blob)return;\n  // Reconstruct readable responses so CDN signatures and headers are not saved.\n  payload=new Response(blob,{headers:{\"Content-Type\":blob.type}})\n }\n await serial(async()=>{\n  if(!current())return;\n  const cache=await caches.open(opaque?OPAQUE:READABLE),cap=opaque?MAX_OPAQUE:MAX_READABLE;\n  await cache.delete(cacheKey(key),{ignoreSearch:true});\n  const remaining=[];\n  for(const req of await cache.keys()){\n   const params=new URL(req.url).searchParams,stamp=Number(params.get(\"d\"));\n   if(!Number.isFinite(stamp)||stamp<day()-TTL_DAYS+1||stamp>day())await cache.delete(req);\n   else remaining.push({req,priority:params.get(\"p\")===\"1\"})\n  }\n  // Reserve at most half the entries for the first visible album screen,\n  // so scrolling far down does not evict the entire next-launch preview.\n  if(priority){\n   const pinned=remaining.filter(x=>x.priority);\n   for(let i=0;i<=pinned.length-Math.floor(cap/2);i++){\n    await cache.delete(pinned[i].req);remaining.splice(remaining.indexOf(pinned[i]),1)\n   }\n  }\n  while(remaining.length>=cap){\n   let i=remaining.findIndex(x=>!x.priority);if(i<0)i=0;\n   await cache.delete(remaining[i].req);remaining.splice(i,1)\n  }\n  if(current())await cache.put(cacheKey(key)+\"?d=\"+day()+\"&p=\"+(priority?1:0),payload)\n })\n}\nasync function upstreamThumbnail(url){\n const origin=new URL(url).origin,opts={credentials:\"omit\",referrerPolicy:\"no-referrer\",redirect:\"follow\"};\n let policy=corsModes.get(origin);\n if(!policy){\n  const attempt=fetch(url,{...opts,mode:\"cors\"}).catch(()=>null);\n  policy=attempt.then(r=>!!r);corsModes.set(origin,policy);\n  if(corsModes.size>32)corsModes.delete(corsModes.keys().next().value);\n  const r=await attempt;if(r)return r\n }else if(await policy){\n  try{return await fetch(url,{...opts,mode:\"cors\"})}catch{corsModes.set(origin,Promise.resolve(false))}\n }\n return fetch(url,{...opts,mode:\"no-cors\"})\n}\nasync function serveThumbnail(e,key){\n const mapped=routes.get(e.clientId+\":\"+key),gen=generation,revision=keyRevisions.get(key);\n if(!mapped||mapped.until<Date.now()||e.request.mode!==\"no-cors\")return {response:new Response(null,{status:404})};\n try{\n  const hit=await cachedThumbnail(key);\n  if(gen!==generation)return {response:new Response(null,{status:404})};\n  if(hit)return {response:hit}\n }catch{/* Cache Storage may be disabled or evicted; network still works. */}\n if(!mapped.url||gen!==generation)return {response:new Response(null,{status:404})};\n try{\n  const response=await upstreamThumbnail(mapped.url);\n  if(gen!==generation)return {response:new Response(null,{status:404})};\n  if(response.type!==\"opaque\"&&!response.ok)return {response:new Response(null,{status:404})};\n  const copy=response.clone();\n  return {response,persist:()=>persistThumbnail(key,copy,gen,revision,mapped.priority)}\n }catch{return {response:new Response(null,{status:502})}}\n}\nself.addEventListener(\"fetch\",e=>{\n const u=new URL(e.request.url);\n if(e.request.method!==\"GET\"||u.origin!==self.location.origin)return;\n const match=u.pathname.match(/^\\/@gallery-thumb\\/([a-f0-9]{64})$/);\n if(match&&e.request.destination===\"image\"){\n  const job=serveThumbnail(e,match[1]);\n  e.respondWith(job.then(r=>r.response));e.waitUntil(job.then(r=>r.persist?.()).catch(()=>{}));return\n }\n if([\"/@gallery.css\",\"/@gallery.js\",\"/@gallery.webmanifest\"].includes(u.pathname))e.respondWith(fetch(e.request))\n});\n"
const icons: Record<string,string> = {"180":"","192":"","512":""}
export function galleryIcon(size: string) { const data=icons[size];return data ? Uint8Array.from(atob(data),c=>c.charCodeAt(0)) : null }
